import React, { useState, useEffect } from 'react';
import { Card, Button, api } from '../App';

export default function ImportPage() {
  const [catFile,    setCatFile]    = useState(null);
  const [soldFile,   setSoldFile]   = useState(null);
  const [catResult,  setCatResult]  = useState(null);
  const [soldResult, setSoldResult] = useState(null);
  const [uploading,  setUploading]  = useState(false);
  const [catDrag,    setCatDrag]    = useState(false);
  const [soldDrag,   setSoldDrag]   = useState(false);

  const [merged,      setMerged]      = useState([]);
  const [saleNos,     setSaleNos]     = useState([]);
  const [selSale,     setSelSale]     = useState('');
  const [gradeFilter, setGradeFilter] = useState('');
  const [markFilter,  setMarkFilter]  = useState('');
  const [search,      setSearch]      = useState('');

  const loadSaleNos = () =>
    api.get('/import/sale-numbers')
       .then(r => { setSaleNos(r.data); if (r.data[0]) setSelSale(String(r.data[0].sale_no)); })
       .catch(() => {});

  useEffect(() => { loadSaleNos(); }, []);

  useEffect(() => {
    if (!selSale) return;
    api.get(`/catalogue/merged?sale_no=${selSale}`).then(r => setMerged(r.data)).catch(() => {});
  }, [selSale]);

  const handleFile = (f, type) => {
    if (!f) return;
    const ext = f.name.split('.').pop().toLowerCase();
    if (!['xlsx','xls','csv'].includes(ext)) { alert('Only .xlsx / .xls / .csv allowed'); return; }
    if (type === 'cat')  setCatFile(f);
    else                 setSoldFile(f);
  };

  // Single upload function — uploads whichever files are selected
  const uploadAll = async () => {
    if (!catFile && !soldFile) {
      alert('Please select at least one file to upload.');
      return;
    }
    setUploading(true);
    setCatResult(null);
    setSoldResult(null);

    let lastSaleNo = selSale;

    // Upload catalogue first (so sold list can reference it)
    if (catFile) {
      try {
        const fd = new FormData(); fd.append('file', catFile);
        const r = await api.post('/import/catalogue', fd);
        setCatResult(r.data);
        if (r.data.sale_no) lastSaleNo = String(r.data.sale_no);
      } catch (e) {
        setCatResult({ error: e.response?.data?.error || e.message });
      }
    }

    // Upload sold list second
    if (soldFile) {
      try {
        const fd = new FormData(); fd.append('file', soldFile);
        const r = await api.post('/import/sold-list', fd);
        setSoldResult(r.data);
      } catch (e) {
        setSoldResult({ error: e.response?.data?.error || e.message });
      }
    }

    // Reload
    await loadSaleNos();
    if (lastSaleNo) {
      setSelSale(lastSaleNo);
      api.get(`/catalogue/merged?sale_no=${lastSaleNo}`).then(r => setMerged(r.data)).catch(() => {});
    }

    setUploading(false);
  };

  const canUpload = !!(catFile || soldFile);

  // Filter values
  const grades = [...new Set(merged.map(r => r.grade).filter(Boolean))].sort();
  const marks  = [...new Set(merged.map(r => r.garden).filter(Boolean))].sort();
  const filtered = merged.filter(r =>
    (!gradeFilter || r.grade  === gradeFilter) &&
    (!markFilter  || r.garden === markFilter) &&
    (!search || (r.garden||'').toLowerCase().includes(search.toLowerCase()) ||
                (r.origin||'').toLowerCase().includes(search.toLowerCase()) ||
                (r.lot_no||'').toLowerCase().includes(search.toLowerCase()))
  );

  const fmtPrice = (min, max) => {
    if (!min && !max) return <span style={{ color: '#ccc' }}>—</span>;
    if (min && max && Math.abs(parseFloat(min) - parseFloat(max)) > 0.5)
      return <b style={{ color: '#1a3c5e' }}>₹{Number(min).toFixed(0)} – ₹{Number(max).toFixed(0)}</b>;
    return <b style={{ color: '#1a3c5e' }}>₹{Number(min || max).toFixed(0)}</b>;
  };

  const DropZone = ({ label, file, onFile, drag, setDrag, inputId, color }) => (
    <div style={{ flex: 1 }}>
      <div style={{ fontSize: 12, fontWeight: 700, color, marginBottom: 8, textTransform: 'uppercase', letterSpacing: 0.5 }}>
        {label}
      </div>
      <div
        onDragOver={e => { e.preventDefault(); setDrag(true); }}
        onDragLeave={() => setDrag(false)}
        onDrop={e => { e.preventDefault(); setDrag(false); onFile(e.dataTransfer.files[0]); }}
        onClick={() => document.getElementById(inputId).click()}
        style={{
          border: `2px dashed ${drag ? color : (file ? color : '#cbd5e0')}`,
          borderRadius: 8, padding: '18px 14px', textAlign: 'center', cursor: 'pointer',
          background: file ? (color === '#1a3c5e' ? '#eff6ff' : '#f0fdf4') : '#fafbfc',
          transition: 'all 0.2s', minHeight: 80, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'
        }}>
        <input id={inputId} type="file" accept=".xlsx,.xls,.csv" style={{ display: 'none' }}
          onChange={e => { if (e.target.files[0]) onFile(e.target.files[0]); }} />
        {file ? (
          <>
            <div style={{ fontSize: 22, marginBottom: 4 }}>📄</div>
            <div style={{ fontSize: 13, fontWeight: 700, color: color }}>{file.name}</div>
            <div style={{ fontSize: 11, color: '#888', marginTop: 2 }}>{(file.size / 1024).toFixed(0)} KB · click to change</div>
          </>
        ) : (
          <>
            <div style={{ fontSize: 28, marginBottom: 4 }}>📥</div>
            <div style={{ fontSize: 13, color: '#888' }}>Drop file or <span style={{ color, fontWeight: 700 }}>browse</span></div>
            <div style={{ fontSize: 11, color: '#aaa', marginTop: 2 }}>.xlsx · .xls · .csv</div>
          </>
        )}
      </div>
    </div>
  );

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>📥 Import Files</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>
        Select both Catalogue and Sold List files, then click <b>Upload Both</b> to import together.
      </p>

      {/* ── Combined upload card ── */}
      <Card style={{ marginBottom: 20 }}>
        {/* Two drop zones side by side */}
        <div style={{ display: 'flex', gap: 20, marginBottom: 16 }}>
          <DropZone
            label="📘 Catalogue Sheet"
            file={catFile}
            onFile={f => handleFile(f, 'cat')}
            drag={catDrag}
            setDrag={setCatDrag}
            inputId="fu-cat"
            color="#1a3c5e"
          />
          <DropZone
            label="📗 Sold List"
            file={soldFile}
            onFile={f => handleFile(f, 'sold')}
            drag={soldDrag}
            setDrag={setSoldDrag}
            inputId="fu-sold"
            color="#1a7a4a"
          />
        </div>

        {/* Results row */}
        {(catResult || soldResult) && (
          <div style={{ display: 'flex', gap: 16, marginBottom: 14 }}>
            {catResult && (
              <div style={{ flex: 1, fontSize: 13, padding: '8px 12px', borderRadius: 6,
                background: catResult.error ? '#fee2e2' : '#f0fdf4',
                color: catResult.error ? '#991b1b' : '#166534', border: `1px solid ${catResult.error ? '#fecaca' : '#bbf7d0'}` }}>
                <b>Catalogue:</b>{' '}
                {catResult.error
                  ? `❌ ${catResult.error}`
                  : `✅ ${catResult.imported} imported · ${catResult.skipped} skipped${catResult.sale_no ? ` · Sale #${catResult.sale_no}` : ''}`
                }
                {catResult.errors?.slice(0,2).map((e,i) => <div key={i} style={{ fontSize:11, marginTop:2 }}>• {e}</div>)}
              </div>
            )}
            {soldResult && (
              <div style={{ flex: 1, fontSize: 13, padding: '8px 12px', borderRadius: 6,
                background: soldResult.error ? '#fee2e2' : '#f0fdf4',
                color: soldResult.error ? '#991b1b' : '#166534', border: `1px solid ${soldResult.error ? '#fecaca' : '#bbf7d0'}` }}>
                <b>Sold List:</b>{' '}
                {soldResult.error
                  ? `❌ ${soldResult.error}`
                  : `✅ ${soldResult.imported} imported · ${soldResult.skipped} skipped`
                }
              </div>
            )}
          </div>
        )}

        {/* Single upload button + clear */}
        <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
          <Button
            onClick={uploadAll}
            disabled={!canUpload || uploading}
            variant="primary"
            style={{ padding: '10px 32px', fontSize: 14, fontWeight: 700, background: canUpload ? '#1a3c5e' : '#94a3b8' }}>
            {uploading ? '⏳ Uploading…' : '⬆ Upload Both Files'}
          </Button>
          {(catFile || soldFile) && (
            <Button variant="outline" size="sm" onClick={() => { setCatFile(null); setSoldFile(null); setCatResult(null); setSoldResult(null); }}>
              Clear All
            </Button>
          )}
          {!catFile && !soldFile && (
            <span style={{ fontSize: 12, color: '#aaa' }}>Select Catalogue and/or Sold List files above first</span>
          )}
          {(catFile || soldFile) && (
            <span style={{ fontSize: 12, color: '#555' }}>
              {catFile && soldFile ? '✓ Both files ready' : catFile ? '⚠ Only Catalogue selected (no Sold List)' : '⚠ Only Sold List selected (no Catalogue)'}
            </span>
          )}
        </div>

        {/* Mapping explanation */}
        <div style={{ marginTop: 14, padding: '10px 14px', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 8, fontSize: 12, color: '#92400e' }}>
          <b>How merging works:</b> The Catalogue and Sold List are matched by <b>Mark + Grade</b>.
          For each Mark+Grade combination, the system finds the Min and Max <b>DealPrice</b> from the Sold List
          across all past sales and shows it as the price range (e.g. ₹186 – ₹236).
          This gives you the historical price range for each garden's tea by grade.
        </div>
      </Card>

      {/* ── Merged data table ── */}
      <Card>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12, flexWrap: 'wrap', gap: 10 }}>
          <div>
            <h3 style={{ fontSize: 15, marginBottom: 2 }}>📋 Catalogue + Sold List Merged</h3>
            {merged.length > 0 && (
              <div style={{ fontSize: 12, color: '#888' }}>Showing {filtered.length} of {merged.length} lots</div>
            )}
          </div>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
            {saleNos.length > 0 && (
              <select value={selSale} onChange={e => setSelSale(e.target.value)}
                style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }}>
                {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
              </select>
            )}
            <select value={gradeFilter} onChange={e => setGradeFilter(e.target.value)}
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }}>
              <option value="">All Grades</option>
              {grades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <select value={markFilter} onChange={e => setMarkFilter(e.target.value)}
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }}>
              <option value="">All Marks</option>
              {marks.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search lot, mark…"
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, width: 130 }} />
            {(gradeFilter || markFilter || search) && (
              <Button size="sm" variant="outline" onClick={() => { setGradeFilter(''); setMarkFilter(''); setSearch(''); }}>Clear</Button>
            )}
          </div>
        </div>

        {filtered.length === 0 ? (
          <div style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>
            {selSale ? 'No data. Upload Catalogue first.' : 'Select a sale number above.'}
          </div>
        ) : (
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ background: '#1a3c5e', color: '#fff' }}>
                  {['Sale No','Lot No','Garden (Mark)','Origin (Location)','Grade','Bags','Net Wt','Min–Max Price ₹','Broker'].map(h => (
                    <th key={h} style={{ padding: '8px 10px', textAlign: 'left', fontWeight: 600, whiteSpace: 'nowrap' }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtered.slice(0, 500).map((row, i) => (
                  <tr key={i} style={{ borderBottom: '1px solid #f0f4f8', background: i % 2 === 0 ? '#fff' : '#fafbfc' }}>
                    <td style={{ padding: '6px 10px', fontWeight: 600 }}>{row.sale_no}</td>
                    <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11, color: '#1a3c5e', fontWeight: 700 }}>{row.lot_no}</td>
                    <td style={{ padding: '6px 10px', fontWeight: 700, color: '#1a3c5e' }}>{row.garden}</td>
                    <td style={{ padding: '6px 10px', fontSize: 11, color: '#777' }}>{row.origin || '—'}</td>
                    <td style={{ padding: '6px 10px' }}>
                      <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{row.grade}</span>
                    </td>
                    <td style={{ padding: '6px 10px' }}>{row.bags || '—'}</td>
                    <td style={{ padding: '6px 10px' }}>{row.net_wt || '—'}</td>
                    <td style={{ padding: '6px 10px' }}>{fmtPrice(row.min_deal_price, row.max_deal_price)}</td>
                    <td style={{ padding: '6px 10px', color: '#888', fontSize: 11 }}>{row.broker || '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            {filtered.length > 500 && (
              <div style={{ padding: 10, textAlign: 'center', color: '#888', fontSize: 12 }}>
                Showing 500 of {filtered.length}. Use filters to narrow.
              </div>
            )}
          </div>
        )}
      </Card>
    </div>
  );
}
